/** In-memory FileSystem. `backups` records every backup copy made. */
export function memoryFs(initial: Record<string, string> = {}) {
  const files = new Map(Object.entries(initial));
  let n = 0;
  const backups: string[] = [];
  const fs: FileSystem = {
    async readText(path) {
      return files.get(path) ?? null;
    },
    async writeText(path, contents, backupFirst) {
      let backup: string | null = null;
      const existing = files.get(path);
      if (backupFirst && existing !== undefined) {
        backup = `C:\\Users\\test\\AppData\\Roaming\\PrismShell\\backups\\copy-${++n}.json`;
        files.set(backup, existing);
        backups.push(backup);
      }
      files.set(path, contents);
      return backup;
    },
    async removePath(path) {
      for (const k of [...files.keys()]) {
        if (k === path || k.startsWith(path + "\\")) files.delete(k);
      }
    },
    async copyFile(from, to) {
      const v = files.get(from);
      if (v === undefined) throw new Error(`missing ${from}`);
      files.set(to, v);
    },
  };
  return { fs, files, backups };
}
